<?php require __DIR__.'/../app/bootstrap.php';if(!empty($_SESSION['user'])){header('Location:index.php');exit;}$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$ip=$_SERVER['REMOTE_ADDR']??'';$s=$pdo->prepare("SELECT COUNT(*) FROM login_attempts WHERE attempted_at>NOW()-INTERVAL 15 MINUTE AND (ip_address=? OR username=?)");$s->execute([$ip,$email]);if($s->fetchColumn()>=10)$err='Too many attempts. Try later.';else{$s=$pdo->prepare("SELECT * FROM users WHERE email=? AND active=1");$s->execute([$email]);$u=$s->fetch();$pdo->prepare("INSERT INTO login_attempts(username,ip_address)VALUES(?,?)")->execute([$email,$ip]);if($u&&password_verify($pass,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];audit($pdo,$u['id'],'login');header('Location:index.php');exit;}$err='Email or password salah.';}}
?><!doctype html><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Login</title><style>body{font:15px Arial;background:#0f172a;display:grid;place-items:center;min-height:100vh}.box{background:#fff;width:360px;padding:30px;border-radius:15px}input{width:100%;box-sizing:border-box;padding:11px;margin:6px 0 15px;border:1px solid #ddd;border-radius:7px}button{width:100%;padding:11px;background:#2563eb;color:#fff;border:0;border-radius:7px}.err{color:#991b1b;background:#fee2e2;padding:10px;border-radius:7px}</style><div class=box><h1>🔧 ServisPro</h1><?php if($err):?><p class=err><?=e($err)?></p><?php endif;?><form method=post><input type=hidden name=csrf value="<?=e(csrf())?>"><label>Email</label><input name=email type=email required><label>Password</label><input name=password type=password required><button>Masuk</button></form></div>